import { useState, useEffect } from "react";

const GlobalStyles = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;700;800&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500&display=swap');
    body { font-family: 'DM Sans', sans-serif; margin: 0; }
    .font-syne { font-family: 'Syne', sans-serif; }

    @keyframes fade-up {
      from { opacity: 0; transform: translateY(20px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes float {
      0%,100% { transform: translateY(0) rotate(-2deg); }
      50%     { transform: translateY(-14px) rotate(2deg); }
    }
    @keyframes shimmer {
      0%   { background-position: -200% center; }
      100% { background-position:  200% center; }
    }
    @keyframes drift1 {
      0%,100% { transform: translate(0,0) rotate(0deg); }
      33%     { transform: translate(8px,-12px) rotate(4deg); }
      66%     { transform: translate(-6px,6px) rotate(-3deg); }
    }
    @keyframes drift2 {
      0%,100% { transform: translate(0,0) rotate(0deg); }
      33%     { transform: translate(-10px,8px) rotate(-5deg); }
      66%     { transform: translate(6px,-10px) rotate(3deg); }
    }
    @keyframes blink {
      0%,100% { opacity: 1; } 50% { opacity: 0; }
    }

    .anim-fade-up  { animation: fade-up .6s ease both; }
    .anim-d1 { animation-delay: .1s; }
    .anim-d2 { animation-delay: .2s; }
    .anim-d3 { animation-delay: .3s; }
    .anim-d4 { animation-delay: .4s; }

    .float-emoji { animation: float 4s ease-in-out infinite; }
    .drift1 { animation: drift1 7s ease-in-out infinite; }
    .drift2 { animation: drift2 9s ease-in-out infinite; }
    .cursor-blink { animation: blink 1s step-end infinite; }

    .shimmer-btn {
      background: linear-gradient(90deg,#1A4A8A 0%,#2E7DF7 45%,#1A4A8A 100%);
      background-size: 200% auto;
      animation: shimmer 3s linear infinite;
    }
    .shimmer-btn:hover { box-shadow: 0 8px 24px rgba(46,125,247,.4); }

    .dot-grid {
      background-image: radial-gradient(circle, #2E7DF712 1px, transparent 1px);
      background-size: 28px 28px;
    }

    .glitch {
      position: relative;
    }
    .glitch::before, .glitch::after {
      content: attr(data-text);
      position: absolute;
      inset: 0;
      font-family: 'Syne', sans-serif;
      font-weight: 800;
    }
    .glitch::before {
      color: #2E7DF7;
      clip-path: polygon(0 0, 100% 0, 100% 35%, 0 35%);
      transform: translate(-3px, 0);
      animation: glitch1 4s infinite;
    }
    .glitch::after {
      color: #f87171;
      clip-path: polygon(0 65%, 100% 65%, 100% 100%, 0 100%);
      transform: translate(3px, 0);
      animation: glitch2 4s infinite;
    }
    @keyframes glitch1 {
      0%,94%,100% { transform: translate(-3px,0); opacity: 0; }
      95%          { transform: translate(-3px,0); opacity: .7; }
      96%          { transform: translate(3px,0);  opacity: .7; }
      97%          { transform: translate(-3px,0); opacity: 0; }
    }
    @keyframes glitch2 {
      0%,94%,100% { transform: translate(3px,0);  opacity: 0; }
      95%          { transform: translate(3px,0);  opacity: .6; }
      96%          { transform: translate(-3px,0); opacity: .6; }
      97%          { transform: translate(3px,0);  opacity: 0; }
    }
  `}</style>
);

const suggestions = [
  { label: "Home",           href: "/",                emoji: "🏠" },
  { label: "Find internships", href: "/student/search", emoji: "🔍" },
  { label: "Sign in",        href: "/login",            emoji: "🔑" },
  { label: "Create account", href: "/register",         emoji: "✨" },
];

export default function NotFound() {
  const [typed, setTyped] = useState("");
  const full = "/404-not-found";

  useEffect(() => {
    let i = 0;
    const id = setInterval(() => {
      i++;
      setTyped(full.slice(0, i));
      if (i >= full.length) clearInterval(id);
    }, 80);
    return () => clearInterval(id);
  }, []);
  return (
    <>
      <GlobalStyles />
      <div className="min-h-screen bg-slate-950 flex flex-col overflow-hidden relative">

        {/* Background */}
        <div className="absolute inset-0 dot-grid" />
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-blue-600/10 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 right-0 w-80 h-80 bg-indigo-900/20 rounded-full blur-3xl pointer-events-none" />

        {/* Floating decorative elements */}
        <div className="drift1 absolute top-24 left-[10%] text-4xl opacity-20 pointer-events-none">🧭</div>
        <div className="drift2 absolute top-40 right-[8%]  text-3xl opacity-15 pointer-events-none">📡</div>
        <div className="drift1 absolute bottom-32 left-[15%] text-2xl opacity-10 pointer-events-none">🔭</div>
        <div className="drift2 absolute bottom-20 right-[12%] text-3xl opacity-15 pointer-events-none">🛸</div>

        {/* Nav */}
        <nav className="relative px-6 md:px-10 py-6 flex justify-between items-center">
          <a href="/" className="font-syne font-extrabold text-xl text-white tracking-tight">
            Stag<span className="text-blue-400">.</span>io
          </a>
          <a href="/" className="text-xs font-medium text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-4 py-2 rounded-lg transition-all duration-200">
            ← Back to home
          </a>
        </nav>

        {/* Main content */}
        <div className="flex-1 flex flex-col items-center justify-center px-6 text-center relative">

          {/* Big 404 */}
          <div className="anim-fade-up mb-6 relative">
            <div
              data-text="404"
              className="glitch font-syne font-extrabold text-white select-none"
              style={{ fontSize: "clamp(7rem, 20vw, 14rem)", lineHeight: 1, letterSpacing: "-4px", opacity: .08 }}
            >
              404
            </div>
            {/* Floating emoji over the 404 */}
            <div className="float-emoji absolute inset-0 flex items-center justify-center text-6xl md:text-8xl">
              🗺️
            </div>
          </div>

          {/* Terminal line */}
          <div className="anim-fade-up anim-d1 font-mono text-xs text-slate-500 bg-slate-900/80 border border-slate-800 rounded-lg px-4 py-2.5 mb-8 flex items-center gap-2">
            <span className="text-emerald-400">stag.io</span>
            <span className="text-slate-600">~</span>
            <span className="text-slate-300">{typed}</span>
            <span className="cursor-blink text-blue-400">|</span>
          </div>

          {/* Message */}
          <h1 className="anim-fade-up anim-d2 font-syne font-extrabold text-white text-3xl md:text-4xl tracking-tight mb-3"
            style={{ letterSpacing: "-1px" }}>
            Lost in the internship galaxy
          </h1>
          <p className="anim-fade-up anim-d3 text-slate-400 font-light leading-relaxed max-w-sm mb-10 text-sm md:text-base">
            The page you're looking for doesn't exist — or has been moved.
            Let's get you back on track.
          </p>

          {/* Suggestions grid */}
          <div className="anim-fade-up anim-d4 grid grid-cols-2 md:grid-cols-4 gap-3 w-full max-w-xl mb-10">
            {suggestions.map(({ label, href, emoji }) => (
              <a
                key={label}
                href={href}
                className="flex flex-col items-center gap-2 bg-slate-900/80 border border-slate-800 hover:border-blue-500/50 hover:bg-slate-800/80 rounded-xl py-4 px-3 transition-all duration-200 group"
              >
                <span className="text-2xl group-hover:scale-110 transition-transform duration-200">{emoji}</span>
                <span className="text-xs font-medium text-slate-400 group-hover:text-white transition-colors">{label}</span>
              </a>
            ))}
          </div>
          {/* Primary CTA */}
          <div className="anim-fade-up anim-d4">
            <a
              href="/"
              className="shimmer-btn inline-block text-white font-semibold px-8 py-3 rounded-xl text-sm transition-all duration-200"
            >
              Take me home →
            </a>
          </div>

        </div>

        {/* Footer */}
        <div className="relative px-6 py-5 text-center">
          <p className="text-xs text-slate-700">
            © 2025–2026 · Stag.io · IFA · L3TI Workshop
          </p>
        </div>

      </div>
    </>
  );
}
